#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

int a[MAXN];
long long ans[MAXN];

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 1; i <= N; i++) {
        scanf("%d", &a[i]);
    }

    // We'll keep piles in a max-heap by (stones, -index) for easier selection
    // But here we simulate directly using two-pointer logic: 
    // At each step, find the pile with max stones (smallest index on tie).
    // Remove stone from the pile with max stones (smallest index if tie) that is not the one we just output.

    int total = 0;
    for (int i = 1; i <= N; i++) total += a[i];

    while (total > 0) {
        // find max pile (by stones, smallest index)
        int max_idx = 1;
        for (int i = 2; i <= N; i++) {
            if (a[i] > a[max_idx] || (a[i] == a[max_idx] && i < max_idx)) {
                max_idx = i;
            }
        }
        // output max_idx
        ans[max_idx]++;

        // remove one stone from the pile with max stones (smallest index if tie), but not from max_idx if possible
        int remove_idx = -1;
        for (int i = 1; i <= N; i++) {
            if (a[i] > 0 && i != max_idx) {
                if (remove_idx == -1 || a[i] > a[remove_idx] || (a[i] == a[remove_idx] && i < remove_idx)) {
                    remove_idx = i;
                }
            }
        }
        if (remove_idx == -1) {
            // only max_idx has stones
            remove_idx = max_idx;
        }
        a[remove_idx]--;
        total--;
    }

    for (int i = 1; i <= N; i++) {
        printf("%lld\n", ans[i]);
    }

    return 0;
}

