int main() {
    int n;
    scanf("%d", &n);
    long long a[n+1];
    for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);

    long long count[n+1];
    memset(count, 0, sizeof(count));

    // Simulate greedily
    // At each step: append index of max pile (smallest index for ties)
    // Then remove from max pile with largest index
    long long cur[n+1];
    for (int i = 1; i <= n; i++) cur[i] = a[i];

    long long total = 0;
    for (int i = 1; i <= n; i++) total += a[i];

    for (long long step = 0; step < total; step++) {
        // find max, smallest index
        long long mx = 0;
        for (int i = 1; i <= n; i++) if (cur[i] > mx) mx = cur[i];
        int append_idx = -1;
        for (int i = 1; i <= n; i++) if (cur[i] == mx) { append_idx = i; break; }
        count[append_idx]++;
        // remove from max pile with largest index
        int rem_idx = -1;
        for (int i = n; i >= 1; i--) if (cur[i] == mx) { rem_idx = i; break; }
        cur[rem_idx]--;
    }
    for (int i = 1; i <= n; i++) printf("%lld\n", count[i]);
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll a;
    int idx;
} Pile;

int cmp_desc_a_asc_idx(const void *p1, const void *p2) {
    const Pile *x = (const Pile *)p1;
    const Pile *y = (const Pile *)p2;
    if (x->a != y->a) return (x->a < y->a) ? 1 : -1;   // descending by a
    return (x->idx > y->idx) - (x->idx < y->idx);      // ascending by idx
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Pile *p = (Pile *)malloc(sizeof(Pile) * N);
    ll *ans = (ll *)calloc(N + 1, sizeof(ll));
    if (!p || !ans) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%lld", &p[i].a);
        p[i].idx = i + 1;
    }

    qsort(p, N, sizeof(Pile), cmp_desc_a_asc_idx);

    ll prev = p[0].a;
    int min_idx = p[0].idx;

    for (int i = 1; i < N; i++) {
        if (p[i].idx < min_idx) min_idx = p[i].idx;

        if (p[i].a < prev) {
            ans[min_idx] += (prev - p[i].a) * (ll)i;
            prev = p[i].a;
        }
    }

    ans[min_idx] += prev * (ll)N;

    for (int i = 1; i <= N; i++) {
        printf("%lld\n", ans[i]);
    }

    free(p);
    free(ans);
    return 0;
}

