public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] a = new int[N];
        int total = 0;
        for (int i = 0; i < N; i++) { a[i] = sc.nextInt(); total += a[i]; }

        long[] count = new long[N];
        // Use a TreeMap: stones -> TreeSet of indices
        TreeMap<Integer, TreeSet<Integer>> map = new TreeMap<>();
        for (int i = 0; i < N; i++) {
            if (a[i] > 0) map.computeIfAbsent(a[i], k -> new TreeSet<>()).add(i);
        }

        for (int step = 0; step < total; step++) {
            int maxStones = map.lastKey();
            int winner = map.get(maxStones).first();
            count[winner]++;
            // Remove from largest-indexed pile with maxStones
            int removeIdx = map.get(maxStones).last();
            map.get(maxStones).remove(removeIdx);
            if (map.get(maxStones).isEmpty()) map.remove(maxStones);
            if (maxStones - 1 > 0) map.computeIfAbsent(maxStones - 1, k -> new TreeSet<>()).add(removeIdx);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) { sb.append(count[i]); if (i < N-1) sb.append('\n'); }
        System.out.println(sb);
    }
}

