public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] a = new long[N];
        long maxA = 0;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextLong();
            if (a[i] > maxA) maxA = a[i];
        }

        // For each height h, cnt[h] = number of piles with a_i >= h.
        long[] diff = new long[(int) maxA + 3];
        for (int i = 0; i < N; i++) {
            if (a[i] > 0) {
                diff[1] += 1;
                diff[(int) a[i] + 1] -= 1;
            }
        }

        long[] cnt = new long[(int) maxA + 2];
        for (int h = 1; h <= maxA; h++) {
            cnt[h] = cnt[h - 1] + diff[h];
        }

        long[] ans = new long[N];

        // Let p_i = max(a_1, ..., a_i).
        // Then answer for i is sum over h = p_{i-1}+1 .. p_i of cnt[h].
        long prefMax = 0;
        for (int i = 0; i < N; i++) {
            long newMax = Math.max(prefMax, a[i]);
            long sum = 0;
            for (long h = prefMax + 1; h <= newMax; h++) {
                sum += cnt[(int) h];
            }
            ans[i] = sum;
            prefMax = newMax;
        }

        StringBuilder sb = new StringBuilder();
        for (long v : ans) sb.append(v).append('\n');
        System.out.print(sb.toString());
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    // Max-heap: (-count, index) so that largest count, smallest index comes first
    priority_queue<pair<long long, int>> pq;
    for (int i = 0; i < N; i++) {
        if (a[i] > 0) pq.emplace(a[i], -i);
    }

    vector<long long> ans(N, 0);
    long long steps = 0;

    while (!pq.empty()) {
        auto [cnt, negIdx] = pq.top(); pq.pop();
        int idx = -negIdx;
        long long curCnt = cnt;

        // How many times can we record this index before its count drops below the next max?
        if (!pq.empty()) {
            auto [nextCnt, _] = pq.top();
            long long diff = curCnt - nextCnt;
            // We can record this index diff times, each time removing from some other pile
            // But if no other pile exists, we have to remove from this one
            // Steps so far = total removals already performed
            long long possible = diff;
            ans[idx] += possible;
            steps += possible;
            curCnt -= possible;
            if (curCnt > 0) pq.emplace(curCnt, -idx);
        } else {
            // Last pile remaining
            ans[idx] += curCnt;
            steps += curCnt;
            break;
        }
    }

    for (int i = 0; i < N; i++) cout << ans[i] << "\n";

    return 0;
}

