int main(){
    int n; cin>>n;
    vector<long long> a(n);
    for(auto &x:a) cin>>x;
    vector<long long> cnt(n+1,0);
    // Use multiset of (-count, index)
    multiset<pair<long long,int>> ms;
    for(int i=0;i<n;i++) if(a[i]>0) ms.insert({-a[i],i});
    while(!ms.empty()){
        auto it=ms.begin();
        long long mx=-it->first;
        int idx=it->second;
        cnt[idx+1]++;
        // Remove from largest-indexed pile with max count, if it's not idx, else from idx
        // Find last element with count mx
        auto it2=ms.end(); --it2;
        // if it2 points to something with count mx and index != idx, remove it
        // else remove idx
        if(it2->first==-mx && it2->second!=idx){
            ms.erase(it2);
            // re-insert with count mx-1
            if(mx-1>0) ms.insert({-(mx-1),it2->second});
        } else {
            ms.erase(it);
            if(mx-1>0) ms.insert({-(mx-1),idx});
        }
    }
    for(int i=1;i<=n;i++) cout<<cnt[i]<<"\n";
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> a(N + 1);
    int64 mx = 0;
    for (int i = 1; i <= N; i++) {
        cin >> a[i];
        mx = max(mx, a[i]);
    }

    // freq[v] = number of piles whose size is exactly v
    vector<int64> freq(mx + 1, 0);
    for (int i = 1; i <= N; i++) freq[a[i]]++;

    // ge[t] = number of piles whose size is at least t
    vector<int64> ge(mx + 2, 0);
    for (int64 v = mx; v >= 1; v--) {
        ge[v] = ge[v + 1] + freq[v];
    }

    vector<int64> ans(N + 1, 0);

    // For each i, answer is the largest t such that ge[t] >= i.
    // Since ge[t] is non-increasing in t, this is exactly a_i after sorting
    // in non-increasing order, but we compute directly from counts.
    int cur = 1;
    for (int64 t = mx; t >= 1; t--) {
        while (cur <= N && ge[t] >= cur) {
            ans[cur] = t;
            cur++;
        }
    }

    for (int i = 1; i <= N; i++) {
        cout << ans[i] << '\n';
    }
    return 0;
}
